const now = new Date();
const sevenDaysAgo = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
const sinceIso = sevenDaysAgo.toISOString();

return [
  {
    json: {
      since: sinceIso,
      until: now.toISOString(),
      repo_owner: $json.REPO_OWNER,
      repo_name: $json.REPO_NAME,
      summary_language: $json.SUMMARY_LANGUAGE,
      delivery_channel: $json.DELIVERY_CHANNEL,
      webhook_url: $json.NOTIFICATION_WEBHOOK_URL,
      email_recipient: $json.EMAIL_RECIPIENT
    }
  }
];

const timeConfig = $('Compute Time Window (Past 7 Days)').first().json;
const since = new Date(timeConfig.since);

// 1. Process Commits
let commitsData = [];
try {
  const rawCommits = $('Fetch Weekly Commits').all();
  commitsData = rawCommits.map(item => ({
    sha: (item.json.sha || '').substring(0, 7),
    author: item.json.commit?.author?.name || 'Unknown',
    message: item.json.commit?.message?.split('\n')[0] || '',
    date: item.json.commit?.author?.date
  }));
} catch (e) {
  commitsData = [];
}

// 2. Process Issues (filter out PRs returned by issue endpoint)
let issuesData = [];
try {
  const rawIssues = $('Fetch Closed Issues').all();
  issuesData = rawIssues
    .filter(item => !item.json.pull_request && item.json.closed_at && new Date(item.json.closed_at) >= since)
    .map(item => ({
      number: item.json.number,
      title: item.json.title,
      closed_at: item.json.closed_at,
      user: item.json.user?.login || 'unknown'
    }));
} catch (e) {
  issuesData = [];
}

// 3. Process Merged PRs
let prsData = [];
try {
  const rawPRs = $('Fetch Closed & Merged PRs').all();
  prsData = rawPRs
    .filter(item => item.json.merged_at && new Date(item.json.merged_at) >= since)
    .map(item => ({
      number: item.json.number,
      title: item.json.title,
      merged_at: item.json.merged_at,
      user: item.json.user?.login || 'unknown'
    }));
} catch (e) {
  prsData = [];
}

return [{
  json: {
    repo: `${timeConfig.repo_owner}/${timeConfig.repo_name}`,
    period_start: timeConfig.since,
    period_end: timeConfig.until,
    language: timeConfig.summary_language || 'EN',
    delivery_channel: timeConfig.delivery_channel,
    webhook_url: timeConfig.webhook_url,
    email_recipient: timeConfig.email_recipient,
    stats: {
      total_commits: commitsData.length,
      total_closed_issues: issuesData.length,
      total_merged_prs: prsData.length
    },
    commits: commitsData.slice(0, 50),
    closed_issues: issuesData.slice(0, 30),
    merged_prs: prsData.slice(0, 30)
  }
}];

