const aiResponse = $json;
const aggregated = $('Aggregate & Filter GitHub Data').first().json;

const summaryText = aiResponse.content?.[0]?.text || 'No summary generated.';
const repoName = aggregated.repo;
const stats = aggregated.stats;

return [{
  json: {
    repo: repoName,
    summary_markdown: summaryText,
    stats: stats,
    delivery_channel: aggregated.delivery_channel,
    webhook_url: aggregated.webhook_url,
    email_recipient: aggregated.email_recipient,
    payload_discord: {
      content: `📊 **Weekly Dev Summary for ${repoName}**\n*Period: Past 7 Days | Merged PRs: ${stats.total_merged_prs} | Closed Issues: ${stats.total_closed_issues}*\n\n${summaryText.substring(0, 1800)}...`
    },
    payload_slack: {
      text: `📊 *Weekly Dev Summary for ${repoName}*\n${summaryText}`
    },
    email_subject: `[Weekly Dev Summary] ${repoName} - ${new Date().toISOString().slice(0,10)}`
  }
}];
